import Foundation
// Simulates CPU-heavy work: counts from 0 to `iterations`
// Returns how long it took in milliseconds
func burnCPU(iterations: Int) -> Double {
    let start = Date()
    var total = 0
    for i in 0..<iterations {
        total &+= i       // &+ is overflow-safe addition
    }
    _ = total             // prevent the compiler from optimising the loop away
    return Date().timeIntervalSince(start) * 1000
}

actor WorkProcessor {
    // Isolated: runs on the actor's serial executor
    // Two calls are serialised: the second waits for the first to finish
    func processIsolated(label: String, iterations: Int) async -> Double {
        print("  [\(label)] starting on actor executor...")
        let ms = burnCPU(iterations: iterations)
        print("  [\(label)] done in \(String(format: "%.0f", ms))ms")
        return ms
    }

    // @concurrent: hops off the actor to the global thread pool
    // Two calls can run truly simultaneously on different threads
    @concurrent
    func processConcurrent(label: String, iterations: Int) async -> Double {
        print("  [\(label)] starting on background thread...")
        let ms = burnCPU(iterations: iterations)
        print("  [\(label)] done in \(String(format: "%.0f", ms))ms")
        return ms
    }
}

