actor ArticleCache {
    private var cache: [UUID: Article] = [:]
    func store(_ article: Article) {
        // Article is Sendable — safe to receive from any actor ✅
        cache[article.id] = article
    }
    func retrieve(id: UUID) -> Article? {
        cache[id]
        // Article is Sendable — safe to return to any caller ✅
    }
}

@MainActor
final class ArticleViewModel {
    private let cache = ArticleCache()
    var displayedArticles: [Article] = []
    func loadAndCache() async {
        let article = Article(
            id: UUID(),
            title: "Swift Concurrency Deep Dive",
            wordCount: 2400
        )
        // Passing `article` to the cache actor — Sendable check happens here ✅
        await cache.store(article)
        if let cached = await cache.retrieve(id: article.id) {
            displayedArticles.append(cached)
            print("  Cached and retrieved: \"\(cached.title)\"")
        }
    }
}

final class ThreadSafeCache<Value>: @unchecked Sendable {
    private var store: [String: Value] = [:]
    private let lock = NSLock()
    func set(_ value: Value, for key: String) {
        lock.withLock {
            store[key] = value
        }
    }
    func get(_ key: String) -> Value? {
        lock.withLock {
            store[key]
        }
    }
    func remove(_ key: String) {
        lock.withLock {
            store.removeValue(forKey: key)
        }
    }
    var count: Int {
        lock.withLock { store.count }
    }
}

actor ImageProcessor {
    // ThreadSafeCache is @unchecked Sendable: can be passed across actors ✅
    let resultCache = ThreadSafeCache<String>()
    @concurrent
    func process(imageID: String) async -> String {
        // Simulate CPU-heavy processing
        _ = burnCPU(iterations: 1_000_000)
        let result = "processed-\(imageID)"
        // Write result to the shared cache
        resultCache.set(result, for: imageID)
        return result
    }
}
@MainActor
final class ImageViewModel {
    let processor = ImageProcessor()
    func processAll() async {
        let ids = ["img-1", "img-2", "img-3"]
        // Process all images concurrently via @concurrent
        await withTaskGroup(of: String.self) { group in
            for id in ids {
                group.addTask {
                    await self.processor.process(imageID: id)
                }
            }
            for await result in group {
                print("  Processed: \(result)")
            }
        }
        // Read from the shared cache — safe because ThreadSafeCache uses NSLock
        let cache = await processor.resultCache
        print("  Cache contains \(cache.count) results")
        print("  img-1 → \(cache.get(\"img-1\") ?? \"missing\")")
    }
}

